package kz.bekzat.jwt.dao;
import kz.bekzat.jwt.db.DatabaseConnection; import kz.bekzat.jwt.model.TokenStatus; import org.springframework.stereotype.Repository; import java.sql.*; import java.time.Instant; import java.util.UUID;
@Repository public class RefreshTokenDao { private final DatabaseConnection db; public RefreshTokenDao(DatabaseConnection db){this.db=db;} public Connection connection()throws SQLException{return db.open();} public void insert(Connection c,String user,String hash,String family,Instant expiry)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO refresh_tokens VALUES(?,?,?,?,?,?,?)")){p.setString(1,UUID.randomUUID().toString());p.setString(2,user);p.setString(3,hash);p.setString(4,family);p.setString(5,"ACTIVE");p.setString(6,expiry.toString());p.setString(7,Instant.now().toString());p.executeUpdate();}} public TokenRow find(Connection c,String hash)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT * FROM refresh_tokens WHERE token_hash=?")){p.setString(1,hash);try(ResultSet r=p.executeQuery()){if(!r.next())return null;return new TokenRow(r.getString("user_id"),r.getString("family_id"),TokenStatus.valueOf(r.getString("status")),Instant.parse(r.getString("expires_at")));}}} public int markUsed(Connection c,String hash)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE refresh_tokens SET status='USED' WHERE token_hash=? AND status='ACTIVE'")){p.setString(1,hash);return p.executeUpdate();}} public int revokeFamily(Connection c,String family)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE refresh_tokens SET status='REVOKED' WHERE family_id=? AND status='ACTIVE'")){p.setString(1,family);return p.executeUpdate();}} public record TokenRow(String userId,String familyId,TokenStatus status,Instant expiresAt){} }
